const tabs = ["Upcoming", "Past", "Cancelled"];

export default function BookifyMyTickets() {
  const [activeTab, setActiveTab] = useState("Past");
  const [discountCode, setDiscountCode] = useState("");

  const filtered = allTickets.filter(t => t.status === activeTab);

  return (
    <div style={styles.root}>
      <div style={styles.bgOverlay} />

      {/* NAVBAR */}
      <DarkNavbar />
      {/* PAGE */}
      <div style={styles.page}>

        {/* Heading */}
        <h1 style={styles.heading}>My Tickets</h1>

        {/* Tabs */}
        <div style={styles.tabBar}>
          {tabs.map(tab => (
            <button
              key={tab}
              style={{ ...styles.tab, ...(activeTab === tab ? styles.tabActive : {}) }}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Ticket list */}
        <div style={styles.ticketList}>
          {filtered.length === 0 && (
            <p style={styles.empty}>No {activeTab.toLowerCase()} tickets.</p>
          )}
          {filtered.map(ticket => (
            <div key={ticket.id} style={styles.ticketCard}>
              {/* Poster */}
              <img src={ticket.image} alt={ticket.title} style={styles.poster} />

              {/* Info */}
              <div style={styles.ticketInfo}>
                <h3 style={styles.ticketTitle}>{ticket.title}</h3>
                <p style={styles.ticketSub}>{ticket.subtitle}</p>
                <p style={styles.ticketMeta}>{ticket.date}</p>
                <p style={styles.ticketMeta}>{ticket.location}</p>
                {ticket.count > 0 && (
                  <span style={styles.ticketBadge}>{ticket.count} Ticket{ticket.count > 1 ? "s" : ""}</span>
                )}
              </div>

              {/* Arrow */}
              <span style={styles.arrow}>›</span>
            </div>
          ))}
        </div>

        {/* Discount bar */}
        <div style={styles.discountBar}>
          <div>
            <p style={styles.discountTitle}>Have a discount code?</p>
            <p style={styles.discountSub}>Enter code to access discounts</p>
          </div>
          <button style={styles.discountBtn}>Enter Code</button>
        </div>

      </div>
    </div>
  );
}

